import math


def _parse_item(item):
    """Extract and validate fields from an item dict.

    Returns (sku, on_hand, target, case_pack) or raises ValueError/KeyError/TypeError.
    """
    try:
        sku = item["sku"]
        on_hand = item["on_hand"]
        target = item["target"]
        case_pack = item["case_pack"]
    except (KeyError, TypeError):
        raise ValueError("malformed item")

    if not isinstance(sku, str):
        raise ValueError("sku must be str")
    if not isinstance(on_hand, (int, float)) or isinstance(on_hand, bool):
        raise ValueError("on_hand must be numeric")
    if not isinstance(target, (int, float)) or isinstance(target, bool):
        raise ValueError("target must be numeric")
    if not isinstance(case_pack, (int, float)) or isinstance(case_pack, bool):
        raise ValueError("case_pack must be numeric")
    if case_pack <= 0:
        raise ValueError("case_pack must be positive")

    return sku, on_hand, target, case_pack


def _compute_reorder_quantity(deficit, case_pack):
    """Round deficit up to the nearest multiple of case_pack."""
    return math.ceil(deficit / case_pack) * int(case_pack)


def _build_row(sku, on_hand, target, case_pack, velocity, include_days_of_cover):
    """Build a result row for one item, or return None if no reorder needed."""
    deficit = target - on_hand
    if deficit <= 0:
        return None

    reorder_quantity = _compute_reorder_quantity(deficit, case_pack)
    row = {"sku": sku, "reorder_quantity": reorder_quantity}

    if include_days_of_cover:
        row["days_of_cover_before_reorder"] = int(on_hand) // velocity

    return row


def reorder_plan(
    items: list[dict],
    sales_velocity: dict[str, int],
    include_days_of_cover: bool = False,
) -> list[dict]:
    """
    Compute a reorder plan for inventory items.

    Args:
        items: List of dicts with keys 'sku', 'on_hand', 'target', 'case_pack'.
        sales_velocity: Mapping of sku to sales velocity (units per period).
        include_days_of_cover: When True, include 'days_of_cover_before_reorder'
            in each returned row, computed as on_hand // sales_velocity[sku].

    Returns:
        Sorted list of dicts with 'sku' and 'reorder_quantity' for items
        that need reordering.
    """
    results = []

    for item in items:
        try:
            sku, on_hand, target, case_pack = _parse_item(item)
        except ValueError:
            continue

        velocity = sales_velocity.get(sku)
        if velocity is None or velocity <= 0:
            continue

        row = _build_row(sku, on_hand, target, case_pack, velocity, include_days_of_cover)
        if row is not None:
            results.append(row)

    results.sort(key=lambda x: x["sku"])
    return results

